<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { KeyRound, Plus, RefreshCw, Send, ShieldOff, Webhook } from 'lucide-vue-next'
import { api, apiError } from '../api/client';import type { ApiResponse, Company } from '../types'
import PageHeader from '../components/PageHeader.vue';import SectionTabs from '../components/SectionTabs.vue';import DrawerPanel from '../components/DrawerPanel.vue';import InlineAlert from '../components/InlineAlert.vue';import KeyReveal from '../components/KeyReveal.vue';import StatusBadge from '../components/StatusBadge.vue';import EmptyState from '../components/EmptyState.vue'
interface Key{id:string;name:string;key_prefix:string;permissions:string[];company_ids:string[];allowed_ips:string[];expires_at?:string;last_used_at?:string;is_active:boolean;created_at:string}
interface Hook{id:string;name:string;url:string;events:string[];headers:Record<string,string>;timeout_seconds:number;max_attempts:number;is_active:boolean;created_at:string}
const tab=ref('keys'),keys=ref<Key[]>([]),hooks=ref<Hook[]>([]),companies=ref<Company[]>([]),drawer=ref(false),error=ref(''),success=ref(''),reveal=ref('')
const form=reactive({name:'',permissions:'customers.read,receivables.read,charges.read',company_ids:[] as string[],allowed_ips:'',expires_at:'',url:'',events:'financial.payment.confirmed',secret:'',headers:'{}',timeout_seconds:30,max_attempts:5,is_active:true})
async function load(){try{const [k,h,c]=await Promise.all([api.get<ApiResponse<Key[]>>('/v1/api-keys'),api.get<ApiResponse<Hook[]>>('/v1/outbound-webhooks'),api.get<ApiResponse<Company[]>>('/v1/companies')]);keys.value=k.data.data;hooks.value=h.data.data;companies.value=c.data.data}catch(e){error.value=apiError(e)}}
function open(){Object.assign(form,{name:'',permissions:'customers.read,receivables.read,charges.read',company_ids:[],allowed_ips:'',expires_at:'',url:'',events:'financial.payment.confirmed',secret:'',headers:'{}',timeout_seconds:30,max_attempts:5,is_active:true});drawer.value=true}
async function create(){try{if(tab.value==='keys'){const r=(await api.post<ApiResponse<{api_key:string}>>('/v1/api-keys',{name:form.name,permissions:form.permissions.split(',').map(v=>v.trim()).filter(Boolean),company_ids:form.company_ids,allowed_ips:form.allowed_ips.split(',').map(v=>v.trim()).filter(Boolean),expires_at:form.expires_at||null})).data.data;reveal.value=r.api_key}else{await api.post('/v1/outbound-webhooks',{name:form.name,url:form.url,events:form.events.split(',').map(v=>v.trim()).filter(Boolean),secret:form.secret||null,headers:JSON.parse(form.headers),timeout_seconds:form.timeout_seconds,max_attempts:form.max_attempts,is_active:form.is_active});success.value='Webhook criado.'}drawer.value=false;await load()}catch(e){error.value=apiError(e)}}
async function revoke(item:Key){if(!confirm(`Revogar ${item.name}?`))return;try{await api.delete(`/v1/api-keys/${item.id}`);await load()}catch(e){error.value=apiError(e)}}
async function remove(item:Hook){if(!confirm(`Remover ${item.name}?`))return;try{await api.delete(`/v1/outbound-webhooks/${item.id}`);await load()}catch(e){error.value=apiError(e)}}
async function test(item:Hook){try{await api.post(`/v1/outbound-webhooks/${item.id}/test`);success.value='Entrega de teste enfileirada.'}catch(e){error.value=apiError(e)}}
onMounted(load)
</script>
<template><PageHeader title="API e Webhooks" subtitle="Integrações externas com escopo de empresa, IP permitido, assinatura e retentativa."><button class="btn-secondary" @click="load"><RefreshCw :size="18"/>Atualizar</button><button class="btn-primary" @click="open"><Plus :size="18"/>{{tab==='keys'?'Nova chave':'Novo webhook'}}</button></PageHeader><InlineAlert :message="error" @dismiss="error=''"/><InlineAlert :message="success" type="success" @dismiss="success=''"/><SectionTabs v-model="tab" :items="[{key:'keys',label:'API Keys',count:keys.length},{key:'webhooks',label:'Webhooks de saída',count:hooks.length}]"/><div v-if="tab==='keys'" class="table-wrap"><table class="table"><thead><tr><th>Chave</th><th>Permissões</th><th>Empresas</th><th>Uso</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="item in keys" :key="item.id" class="border-t border-slate-100"><td><p class="font-semibold">{{item.name}}</p><p class="font-mono text-xs text-slate-400">{{item.key_prefix}}…</p></td><td><div class="flex max-w-md flex-wrap gap-1"><span v-for="p in item.permissions.slice(0,8)" :key="p" class="badge bg-slate-100 text-slate-700">{{p}}</span></div></td><td>{{item.company_ids.length||'Todas permitidas pelo escopo'}}</td><td class="text-xs">{{item.last_used_at?new Date(item.last_used_at).toLocaleString('pt-BR'):'Nunca'}}</td><td><StatusBadge :status="item.is_active?'ACTIVE':'REVOKED'"/></td><td class="text-right"><button v-if="item.is_active" class="btn-secondary px-3 py-2 text-rose-600" @click="revoke(item)"><ShieldOff :size="16"/></button></td></tr></tbody></table><EmptyState v-if="!keys.length" title="Nenhuma API key"/></div><div v-else class="grid gap-4 xl:grid-cols-2"><article v-for="item in hooks" :key="item.id" class="card"><div class="flex items-start gap-3"><div class="rounded-xl bg-violet-50 p-2 text-violet-700"><Webhook :size="20"/></div><div class="min-w-0 flex-1"><div class="flex items-center gap-2"><h2 class="font-bold">{{item.name}}</h2><StatusBadge :status="item.is_active?'ACTIVE':'INACTIVE'"/></div><p class="mt-1 truncate text-xs text-slate-500">{{item.url}}</p></div><button class="btn-secondary px-3 py-2" @click="test(item)"><Send :size="16"/>Testar</button><button class="btn-secondary px-3 py-2 text-rose-600" @click="remove(item)"><ShieldOff :size="16"/></button></div><div class="mt-4 flex flex-wrap gap-1"><span v-for="event in item.events" :key="event" class="badge bg-violet-50 text-violet-700">{{event}}</span></div><p class="mt-4 text-xs text-slate-400">Timeout {{item.timeout_seconds}}s · até {{item.max_attempts}} tentativas · assinatura HMAC-SHA256</p></article><EmptyState v-if="!hooks.length" title="Nenhum webhook de saída"/></div><DrawerPanel :open="drawer" :title="tab==='keys'?'Nova API Key':'Novo webhook de saída'" width="xl" @close="drawer=false"><form class="grid gap-4 md:grid-cols-2" @submit.prevent="create"><div class="md:col-span-2"><label class="label">Nome</label><input v-model="form.name" class="input" required/></div><template v-if="tab==='keys'"><div class="md:col-span-2"><label class="label">Permissões separadas por vírgula</label><textarea v-model="form.permissions" class="input" rows="3"/></div><div class="md:col-span-2"><label class="label">Empresas permitidas</label><div class="grid gap-2 rounded-xl border border-slate-200 p-3 sm:grid-cols-2"><label v-for="c in companies" :key="c.id" class="flex gap-2 text-sm"><input v-model="form.company_ids" type="checkbox" :value="c.id"/>{{c.trade_name||c.legal_name}}</label></div></div><div><label class="label">IPs permitidos</label><input v-model="form.allowed_ips" class="input" placeholder="separados por vírgula"/></div><div><label class="label">Expiração</label><input v-model="form.expires_at" type="datetime-local" class="input"/></div></template><template v-else><div class="md:col-span-2"><label class="label">URL HTTPS</label><input v-model="form.url" type="url" class="input" required/></div><div class="md:col-span-2"><label class="label">Eventos separados por vírgula</label><textarea v-model="form.events" class="input" rows="3"/></div><div><label class="label">Segredo opcional</label><input v-model="form.secret" type="password" class="input"/></div><div><label class="label">Headers JSON</label><textarea v-model="form.headers" class="input font-mono text-xs" rows="3"/></div><div><label class="label">Timeout</label><input v-model.number="form.timeout_seconds" type="number" min="1" max="120" class="input"/></div><div><label class="label">Máximo de tentativas</label><input v-model.number="form.max_attempts" type="number" min="1" max="20" class="input"/></div></template><div class="md:col-span-2 flex justify-end gap-2 border-t pt-4"><button type="button" class="btn-secondary" @click="drawer=false">Cancelar</button><button class="btn-primary"><component :is="tab==='keys'?KeyRound:Webhook" :size="16"/>Criar</button></div></form></DrawerPanel><KeyReveal :open="!!reveal" :value="reveal" title="API Key criada" @close="reveal=''"/></template>
